// FleetServiceServer is the server API for FleetService service.
// All implementations should embed UnimplementedFleetServiceServer
// for forward compatibility.
//
// FleetService is the Fleet Manager's surface over a set of CryptOS nodes:
// read aggregation (status, identity, certificates, catalog) plus the
// operator-driven enrollment writes. A single Connect endpoint for the
// manager's web UI.
type FleetServiceServer interface {
	// ListNodes returns a summary for every node the manager knows about.
	ListNodes(context.Context, *ListNodesRequest) (*ListNodesResponse, error)
	// GetNode returns full detail, including the identity chain, for one node.
	GetNode(context.Context, *GetNodeRequest) (*GetNodeResponse, error)
	// ListCertificates returns the aggregated certificate set across nodes,
	// optionally scoped to a single node.
	ListCertificates(context.Context, *ListCertificatesRequest) (*ListCertificatesResponse, error)
	// ListProfiles returns the manager's catalog of certificate issuance
	// profiles. Each is a cryptos.node.v1.CertificateProfile, the same shape a node
	// stores in pki.profiles[], so the catalog is a lossless superset the node
	// accepts verbatim. Operator-readable.
	ListProfiles(context.Context, *ListProfilesRequest) (*ListProfilesResponse, error)
	// CreateProfile adds a new certificate profile to the manager's catalog.
	// The profile name must be unique. Admin-gated and audited.
	CreateProfile(context.Context, *CreateProfileRequest) (*CreateProfileResponse, error)
	// UpdateProfile replaces an existing catalog profile, matched by name.
	// Admin-gated and audited.
	UpdateProfile(context.Context, *UpdateProfileRequest) (*UpdateProfileResponse, error)
	// DeleteProfile removes a catalog profile by name. Non-cascading: it does
	// not touch any node's existing pki.profiles[]. Admin-gated and audited.
	DeleteProfile(context.Context, *DeleteProfileRequest) (*DeleteProfileResponse, error)
	// ApplyProfileToNode pushes a catalog profile onto a managed node: the
	// manager fetches the node's full config, inserts-or-replaces the named
	// profile in pki.profiles[] (matched by name), and applies the whole config
	// back via the node's ApplyConfig. Admin-gated and audited.
	ApplyProfileToNode(context.Context, *ApplyProfileToNodeRequest) (*ApplyProfileToNodeResponse, error)
	// ListAdapters returns the manager's catalog of enrollment protocol
	// adapters.
	ListAdapters(context.Context, *ListAdaptersRequest) (*ListAdaptersResponse, error)
	// SetAdapterEnabled records whether an enrollment protocol adapter is
	// enabled, matched by adapter name. This persists intent; the protocol
	// engines that serve enrollment requests ship in a later program, so an
	// enabled adapter does not yet answer requests. Admin-gated and audited.
	SetAdapterEnabled(context.Context, *SetAdapterEnabledRequest) (*SetAdapterEnabledResponse, error)
	// SetNodeProtocol switches one enrolment protocol on or off on one managed
	// node. The manager fetches the node's config, sets that protocol block's
	// enabled flag, leaves its other settings as the node returned them, and
	// applies it back through the node's ApplyConfig. Write-only secrets come
	// back blank from the node and are sent blank, so the node keeps what it
	// stores; they never reach the manager. The other protocol blocks are left
	// out of the apply, so the node keeps them unchanged. A switch is
	// reboot-required: the node stores it and the listener changes at the next
	// boot, and NodeSummary.reboot_required stays true until the node reports it
	// running in the new state. The node's refusal (a Root refusing
	// enabled=true, a block that fails validation) is returned as its error.
	// Admin-gated and audited.
	SetNodeProtocol(context.Context, *SetNodeProtocolRequest) (*SetNodeProtocolResponse, error)
	// ListAudit returns the manager's audit log.
	ListAudit(context.Context, *ListAuditRequest) (*ListAuditResponse, error)
	// ListEnrollments returns the manager's pending and resolved enrollment
	// requests.
	ListEnrollments(context.Context, *ListEnrollmentsRequest) (*ListEnrollmentsResponse, error)
	// CreateEnrollment opens a new enrollment request (LINK a node or provision a
	// SUBORDINATE CA); the manager verifies attestation for LINK.
	CreateEnrollment(context.Context, *CreateEnrollmentRequest) (*CreateEnrollmentResponse, error)
	// ApproveEnrollment approves a pending request (LINK -> ApplyConfig managed
	// state; SUBORDINATE -> CSR-ferry).
	ApproveEnrollment(context.Context, *ApproveEnrollmentRequest) (*ApproveEnrollmentResponse, error)
	// RejectEnrollment rejects a pending request with a reason.
	RejectEnrollment(context.Context, *RejectEnrollmentRequest) (*RejectEnrollmentResponse, error)
	// WhoAmI echoes the operator identity the manager verified from the
	// presented client certificate (subject CN, cert serial, access level).
	WhoAmI(context.Context, *WhoAmIRequest) (*WhoAmIResponse, error)
	// RevokeCertificate revokes an issued certificate on the node that issued
	// it, identified by node and hex serial, with an RFC 5280 reason code.
	RevokeCertificate(context.Context, *RevokeCertificateRequest) (*RevokeCertificateResponse, error)
	// GetCertificate fetches an issued certificate and its chain, PEM encoded,
	// from the node that issued it, identified by node name and hex serial.
	// Readable at viewer level and above; a read, so it is not audited. NotFound
	// if the node has no certificate with that serial.
	GetCertificate(context.Context, *GetCertificateRequest) (*GetCertificateResponse, error)
	// IssueLeaf signs a leaf certificate on the named issuing node from a
	// browser-generated PKCS#10 CSR under a named issuance profile. Only the
	// CSR crosses the wire; the leaf private key stays in the browser.
	IssueLeaf(context.Context, *IssueLeafRequest) (*IssueLeafResponse, error)
	// RekeyNode re-keys a subordinate CA node in one orchestrated call: the
	// manager has the child mint a new key + CSR, routes the CSR to the parent
	// (resolved from the child's issuer CN) for signing under profile_name, and
	// delivers the signed chain back to the child. The parent must be a node the
	// manager already knows about.
	RekeyNode(context.Context, *RekeyNodeRequest) (*RekeyNodeResponse, error)
	// GetNodeConfig fetches the current machine configuration of a managed node,
	// so an operator can view it (and the web can edit a subset before applying
	// the whole config back). Operator-gated; a read, so it is not audited.
	GetNodeConfig(context.Context, *GetNodeConfigRequest) (*GetNodeConfigResponse, error)
	// ApplyNodeConfig applies a full machine configuration to a managed node.
	// The config is the fetched baseline with the operator's edits merged in; the
	// node's ApplyConfig is a whole-config replace, so the caller must send the
	// complete config, never a partial one. Admin-gated and audited.
	ApplyNodeConfig(context.Context, *ApplyNodeConfigRequest) (*ApplyNodeConfigResponse, error)
	// ExportCAKey backs up a managed node's CA private key to an encrypted
	// envelope. The node seals the backup with the operator passphrase
	// (Argon2id + AES-256-GCM) so the plaintext key never leaves the node; the
	// manager only relays the envelope through to the caller. The passphrase is
	// used in transit and is never persisted. A TPM-backed node refuses export.
	// Admin-gated and audited (the audit names the node only, never the secret).
	ExportCAKey(context.Context, *ExportCAKeyRequest) (*ExportCAKeyResponse, error)
	// ImportCAKey restores a CA identity onto a fresh managed node from an
	// encrypted envelope produced by ExportCAKey. The node decrypts the envelope
	// with the operator passphrase and adopts the key; it refuses the import if
	// it already holds an identity. The passphrase transits the manager only to
	// reach the node and is never persisted. Admin-gated and audited (the audit
	// names the node and restored subject only, never the secret or envelope).
	ImportCAKey(context.Context, *ImportCAKeyRequest) (*ImportCAKeyResponse, error)
	// CreateOperatorCredentialRequest stores a pending request for an operator
	// credential from a CSR with subject CN=<email>, for the external operator
	// CA to sign out of band. It returns the CSR, the OpenSSL extension section
	// for the level, and the signing command. The request expires after 30
	// days. Admin-gated and audited.
	CreateOperatorCredentialRequest(context.Context, *CreateOperatorCredentialRequestRequest) (*CreateOperatorCredentialRequestResponse, error)
	// ListOperatorCredentialRequests returns credential requests, newest first,
	// optionally filtered by state. Operator-readable.
	ListOperatorCredentialRequests(context.Context, *ListOperatorCredentialRequestsRequest) (*ListOperatorCredentialRequestsResponse, error)
	// CancelOperatorCredentialRequest cancels a pending request. Admin-gated and
	// audited.
	CancelOperatorCredentialRequest(context.Context, *CancelOperatorCredentialRequestRequest) (*CancelOperatorCredentialRequestResponse, error)
	// RecordOperatorCredential checks and records an operator certificate the
	// external operator CA signed. With request_id, the level, CN and public key
	// must match the pending request, which is then completed; without it, a
	// certificate made entirely out of band is imported. The certificate must
	// chain to the active operator CA and not be recorded already. Admin-gated
	// and audited.
	RecordOperatorCredential(context.Context, *RecordOperatorCredentialRequest) (*RecordOperatorCredentialResponse, error)
	// RevokeOperatorCredential puts an operator credential on the manager's
	// denylist, keyed by issuer and hex serial, with an RFC 5280 reason code.
	// The authz middleware refuses the credential from its next request. A
	// serial the manager never recorded can be denied too. It calls no node and
	// doesn't revoke at the CA: the response warns to revoke there too and
	// publish a new CRL. Admin-gated and audited.
	RevokeOperatorCredential(context.Context, *RevokeOperatorCredentialRequest) (*RevokeOperatorCredentialResponse, error)
	// ListOperatorCredentials returns the operator credentials the manager
	// knows: first-admin, requested, recorded and observed in use, with their
	// issuer and revocation state. Operator-readable.
	ListOperatorCredentials(context.Context, *ListOperatorCredentialsRequest) (*ListOperatorCredentialsResponse, error)
	// ListOperatorCAs returns the operator CAs the manager trusts or has
	// trusted, with their CRL and OCSP state. Operator-readable.
	ListOperatorCAs(context.Context, *ListOperatorCAsRequest) (*ListOperatorCAsResponse, error)
	// RegisterOperatorCA registers a new operator CA after first run, with the
	// same checks, preview and confirm_sha256 step as
	// BootstrapService.RegisterOperatorCA. The new CA becomes active and the
	// previous active CA becomes retiring, still trusted until it is retired.
	// Refused with 1605 ROTATION_IN_PROGRESS while a retiring CA exists.
	// Admin-gated and audited. Every operator-CA write returns 1607 while the
	// operator CA comes from the manager's config file.
	RegisterOperatorCA(context.Context, *RegisterOperatorCARequest) (*RegisterOperatorCAResponse, error)
	// RetireOperatorCA stops trusting an operator CA; every certificate under
	// it is refused from its next request. Refused with 1609 for the last
	// active CA, and refused when the caller's own certificate chains only to
	// it unless i_understand_self_lockout is set. Admin-gated and audited.
	RetireOperatorCA(context.Context, *RetireOperatorCARequest) (*RetireOperatorCAResponse, error)
	// SetOperatorCACRLSource changes an operator CA's CRL source. A new URL or
	// CRL must verify against the CA first; switching to none needs the NO_CRL
	// acknowledgement and cuts off MCP for certificates under the CA.
	// Admin-gated and audited.
	SetOperatorCACRLSource(context.Context, *SetOperatorCACRLSourceRequest) (*SetOperatorCACRLSourceResponse, error)
	// UploadOperatorCRL stores a new CRL for an operator CA whose CRL source is
	// upload. It must verify against the CA and be newer than the stored CRL.
	// Admin-gated and audited.
	UploadOperatorCRL(context.Context, *UploadOperatorCRLRequest) (*UploadOperatorCRLResponse, error)
	// SetOperatorCAOCSP changes an operator CA's OCSP mode. OCSP_MODE_URL must
	// pass a probe of the responder first. Admin-gated and audited.
	SetOperatorCAOCSP(context.Context, *SetOperatorCAOCSPRequest) (*SetOperatorCAOCSPResponse, error)
	// PreviewAdoption performs the trust-on-first-use step of adopting a new
	// node: it dials the maintenance endpoint (no pin yet), captures the
	// self-signed certificate the node presents, and returns its SHA-256
	// fingerprint and subject so the operator can confirm it before adoption.
	// Admin-gated; a read, so it is not audited.
	PreviewAdoption(context.Context, *PreviewAdoptionRequest) (*PreviewAdoptionResponse, error)
	// ListInstallDisks returns the candidate install disks a maintenance node
	// reports, so the adopt wizard can offer a real device to install to instead
	// of a free-text guess. Pinned to the fingerprint confirmed via
	// PreviewAdoption. Admin-gated; a read, so it is not audited.
	ListInstallDisks(context.Context, *ListInstallDisksRequest) (*ListInstallDisksResponse, error)
	// AdoptNode provisions a new maintenance node end to end and streams progress.
	// Pinned to the fingerprint the operator confirmed via PreviewAdoption, the
	// manager applies the initial config, awaits the reboot, waits for the
	// operator to confirm the installed node's certificate fingerprint
	// (ConfirmAdoptionFingerprint), drives the first-boot ceremony, and
	// registers the node. Each streamed message carries a phase (see
	// AdoptNodeResponse) with human-readable detail; the final message sets
	// done. Admin-gated and audited.
	AdoptNode(*AdoptNodeRequest, grpc.ServerStreamingServer[AdoptNodeResponse]) error
	// ConfirmAdoptionFingerprint lets a paused adoption continue. After the node
	// installs and reboots it presents a new management certificate that
	// nothing links to the maintenance fingerprint confirmed via
	// PreviewAdoption, so AdoptNode streams the
	// awaiting-fingerprint-confirmation phase with that certificate's SHA-256
	// and waits. The operator compares it with the Mgmt SHA-256 line on the
	// node's console and sends it back here. On a match (case and colons
	// ignored) the adoption resumes and the presented certificate is what the
	// manager trusts and records; on a mismatch the manager returns
	// InvalidArgument, the adoption stream ends with the error phase, and
	// nothing is recorded. NotFound means no adoption with that ID is waiting.
	// Admin-gated and audited.
	ConfirmAdoptionFingerprint(context.Context, *ConfirmAdoptionFingerprintRequest) (*ConfirmAdoptionFingerprintResponse, error)
	// DecommissionNode remotely wipes a managed node's identity and data via the
	// node's mTLS-served RemoteReset, then reboots it into maintenance. The caller
	// must echo the node's current Root CA CN as confirmation. Admin-gated and
	// audited (the audit names the node and that it was wiped, never any secret).
	DecommissionNode(context.Context, *DecommissionNodeRequest) (*DecommissionNodeResponse, error)
	// RebootNode asks a managed node to perform an orderly reboot or power-off,
	// the way a config change ApplyNodeConfig reported as requires_reboot (or
	// any other staged change surfaced as NodeSummary.reboot_required) takes
	// effect without an out-of-band hypervisor reset. It proxies the node's own
	// Reboot RPC, which requires the same confirmation as ActivateImage: the
	// caller must echo the node's current CA CN, checked by the node itself.
	// Admin-gated (rebooting an issuing CA is an outage of everything that
	// depends on it) and audited.
	RebootNode(context.Context, *RebootNodeRequest) (*RebootNodeResponse, error)
	// RenameNode changes a node's display name. The node is addressed by its
	// stable ID, which never changes, so URLs, audit entries and references
	// recorded against the ID keep pointing at the node. Returns the updated
	// node. NotFound if no node has node_id; AlreadyExists if another node
	// already has new_name; InvalidArgument if new_name is not an RFC 1123 label
	// (1 to 63 lowercase letters, digits and hyphens, starting and ending with a
	// letter or digit). Renaming a node to its current name returns it unchanged
	// and records nothing. Admin-gated and audited (node-renamed, with the old
	// and new names).
	RenameNode(context.Context, *RenameNodeRequest) (*RenameNodeResponse, error)
	// RemoveNode removes a node from the manager's inventory without contacting
	// the node, for a node that is gone (destroyed, or wiped and not coming
	// back). It does not reset or unlink the node; DecommissionNode does that.
	// confirm_name must equal the node's current name. The node's audit
	// history and name history are kept, and its credentials folder is moved
	// aside rather than deleted. NotFound if no node has node_id;
	// InvalidArgument if confirm_name doesn't match; FailedPrecondition while
	// something still depends on the node, such as a pending enrollment that
	// names it. Admin-gated and audited (node-removed, with the name and ID).
	RemoveNode(context.Context, *RemoveNodeRequest) (*RemoveNodeResponse, error)
	// ListMcpKeys returns the MCP agent keys bound to the calling operator's
	// certificate. An admin may set all to list every operator's keys; a
	// non-admin that sets all is refused. The listing never carries a key or its
	// hash. Operator-certificate only: an MCP key can never list keys.
	ListMcpKeys(context.Context, *ListMcpKeysRequest) (*ListMcpKeysResponse, error)
	// RevokeMcpKey revokes an MCP agent key by id. An operator may revoke the
	// keys bound to their own certificate; an admin may revoke any key. The
	// revocation takes effect on the key's next request. Idempotent: revoking an
	// already revoked key returns it unchanged. Operator-certificate only and
	// audited.
	RevokeMcpKey(context.Context, *RevokeMcpKeyRequest) (*RevokeMcpKeyResponse, error)
	// CreateMcpKey mints an MCP agent key bound to the calling operator's
	// certificate serial, for MCP clients that cannot run the OAuth login. It is
	// the same mint and binding as the login flow. The response carries the
	// plaintext key exactly once; the manager stores only its hash, so a lost key
	// is revoked and re-minted, never recovered. The level ceiling may not exceed
	// the caller's own level. Operator-certificate only and audited (the audit
	// names the key id, label and ceiling, never the key).
	CreateMcpKey(context.Context, *CreateMcpKeyRequest) (*CreateMcpKeyResponse, error)
	// ListApprovals returns step-up approval requests, newest first, optionally
	// filtered by status. An approval is raised when an MCP tool call needs a
	// human decision before it runs. Operator-certificate only: an MCP key can
	// never list approvals.
	ListApprovals(context.Context, *ListApprovalsRequest) (*ListApprovalsResponse, error)
	// DecideApproval approves or denies a pending approval by id and returns the
	// updated approval. Operator-certificate only: an MCP key can never decide
	// approvals. The deciding operator's level must be at least the approval's
	// required_level. Audited.
	DecideApproval(context.Context, *DecideApprovalRequest) (*DecideApprovalResponse, error)
}

